    13	/* mod 128 saturating subtract of two 64-bit values in big-endian order */
    14	static int satsub64be(const unsigned char *v1, const unsigned char *v2)
    15	{
    16	    int64_t ret;
    17	    uint64_t l1, l2;
    18	
    19	    n2l8(v1, l1);
    20	    n2l8(v2, l2);
    21	
    22	    ret = l1 - l2;
    23	
    24	    /* We do not permit wrap-around */
    25	    if (l1 > l2 && ret < 0)
    26	        return 128;
    27	    else if (l2 > l1 && ret > 0)
    28	        return -128;
    29	
    30	    if (ret > 128)
    31	        return 128;
    32	    else if (ret < -128)
    33	        return -128;
    34	    else
    35	        return (int)ret;
    36	}
